  <script>
    // Mobile nav
    const navToggle = document.querySelector('[data-nav-toggle]');
    const body = document.body;
    if (navToggle){
      navToggle.addEventListener('click', () => {
        const expanded = navToggle.getAttribute('aria-expanded') === 'true';
        navToggle.setAttribute('aria-expanded', String(!expanded));
        body.classList.toggle('nav-open', !expanded);
      });
      document.addEventListener('keydown', (e)=>{
        if(e.key==='Escape'){ body.classList.remove('nav-open'); navToggle.setAttribute('aria-expanded','false'); }
      });
    }

    // Smooth scroll
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    document.querySelectorAll('a[href^="#"]').forEach(a=>{
      a.addEventListener('click', e=>{
        const id = a.getAttribute('href');
        if(id.length>1){
          const el = document.querySelector(id);
          if(el){
            e.preventDefault();
            const top = el.getBoundingClientRect().top + window.pageYOffset - 16;
            if(prefersReduced){ window.scrollTo(0, top); }
            else { window.scrollTo({top, behavior:'smooth'}); }
          }
        }
      });
    });

    // Reveal on view
    const io = new IntersectionObserver((entries)=>{
      entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('in-view'); io.unobserve(en.target);} });
    }, { threshold:.14 });
    document.querySelectorAll('.reveal').forEach(el=>io.observe(el));

    // FAQ accordion (shared styles via inline)
    document.querySelectorAll('.faq__btn').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const expanded = btn.getAttribute('aria-expanded') === 'true';
        const content = document.getElementById(btn.getAttribute('aria-controls'));
        btn.setAttribute('aria-expanded', String(!expanded));
        if(!expanded){ content.removeAttribute('hidden'); }
        else { content.setAttribute('hidden',''); }
      });
    });

    // Newsletter validation
    const form = document.getElementById('newsletter-form');
    if(form){
      const email = form.querySelector('input[name="email"]');
      const hint = document.getElementById('email-hint');
      form.addEventListener('submit', (e)=>{
        e.preventDefault();
        if(!email.value || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){
          hint.textContent = 'Please enter a valid email address.';
          hint.style.color = '#C44B4B';
          email.setAttribute('aria-invalid','true');
          email.focus();
          return;
        }
        email.removeAttribute('aria-invalid');
        hint.style.color = '#2E9E61';
        form.outerHTML = '<p style="color:#2E9E61;font-weight:700">Welcome—check your inbox for a confirmation.</p>';
      });
    }
  </script>
